 * is none). These templates read no input variable: `inputs` is accepted and not read.
 */
export function step(state, event, selector, inputs) {
  const cs = candidates(state, event);
  if (selector === null ? cs.length > 0 : !cs.some(t => t.id === selector)) return { kind: 'inadmissible', next: state };
  if (selector === null) return { kind: event === null ? 'quiescence' : 'discard', next: state };
  const t = cs.find(x => x.id === selector);
  // M' = M - pre + post; a place above the bound stops the run.
  const marking = { ...state.marking };
  for (const a of t.preset) $set(marking, a.place, $tokens({ marking }, a.place) - a.weight);
  for (const a of t.postset) $set(marking, a.place, $tokens({ marking }, a.place) + a.weight);
  for (const a of t.postset) if (marking[a.place] > BOUND) return halted(state, 'unsafe: ' + a.place + ' would hold ' + marking[a.place] + ' tokens');
  for (const p of Object.keys(marking)) if (marking[p] === 0) delete marking[p];
  // Every action site reads the state before the step and returns its writes (its $apply is the collector
  // passed here); then one $apply writes them all together, as the simulator's parallel assignment.
  const writes = [];
  const written = new Set();
  for (const site of t.actions) {
    let list;
    try { list = site(state, event, (s, w) => w); } catch (e) { return halted(state, 'action: ' + e.message); }
