      if (d === null) return halted(state, 'undeclared: ' + attr + ' of ' + element);
      if (d[3] !== 'stored') return halted(state, 'read-only: ' + attr + ' of ' + element);
      const key = JSON.stringify([element, attr]);
      if (written.has(key)) return halted(state, 'assigned twice: ' + attr + ' of ' + element);
      written.add(key);
      if (d[4] === 'semantic' && !inDomain(value, d[2])) return halted(state, 'outside its domain: ' + attr + ' of ' + element + ' = ' + value);
      writes.push([element, attr, value]);
