    $set(next.derived[d.element], d.attr, value);
  }
  return { kind: 'fired', next };
}

/** What the oracle compares: the marking without its zeros, the attributes and the derived values, all sorted. */
export function observe(state) {
  const sorted = (record, keep) => {
    const out = {};
    for (const k of Object.keys(record || {}).sort()) if (keep(record[k])) $set(out, k, record[k]);
    return out;
  };
  const nested = record => {
    const out = {};
    for (const k of Object.keys(record || {}).sort()) $set(out, k, sorted(record[k], () => true));
    return out;
  };
  return { marking: sorted(state.marking, n => n !== 0), attrs: nested(state.attrs), derived: nested(state.derived) };
}

/** What «Run» calls: up to five steps, each firing the first candidate of the first input that has one, by name. */
export function main() {
  const named = record => {
    const out = {};
    for (const k of Object.keys(record)) $set(out, $own(NAMES, k) ? NAMES[k] : k, record[k]);
    return out;
  };
  const readable = o => ({ marking: named(o.marking), attrs: named(o.attrs), derived: named(o.derived) });
  let state = initial();
  const trace = [{ step: 0, state: readable(observe(state)) }];
  for (let i = 1; i <= 5; i++) {
    const input = [null, ...EVENTS.map(e => e.id)].find(e => candidates(state, e).length > 0);
    if (input === undefined) break;
    const t = candidates(state, input)[0];
    const r = step(state, input, t.id, []);
    trace.push({ step: i, input: input === null ? 'ε' : EVENTS.find(e => e.id === input).name, fired: t.name, kind: r.kind, state: readable(observe(r.next)) });
    state = r.next;
  }
  return trace;
}
